// D42 · Part 2 · 계산 형식과 배치 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d42_quant.ts
//   같은 가중치를 float32 → float16 → int8로 줄이면 크기·읽는 시간은 1/2·1/4, 오차는 조금 늘어난다 + 묶어서 계산하면 요청당 시간이 준다 (작은 행렬로 재현)
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 7;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
const N = 256, B = 32;
const W = Float32Array.from({ length: N * N }, () => (rand() * 2 - 1) * 0.09); // 작은 장난감 모델의 가중치 (진짜 Whisper 아님)
const X = Float32Array.from({ length: B * N }, () => rand() * 2 - 1); // 요청 32개

function matmul(x: Float32Array, w: Float32Array): Float32Array {
  const y = new Float32Array(B * N);
  for (let b = 0; b < B; b++) for (let k = 0; k < N; k++) { const xv = x[b * N + k]; for (let n = 0; n < N; n++) y[b * N + n] += xv * w[k * N + n]; }
  return y;
}
function f16(v: number): number {
  // float16 흉내: 유효숫자 11비트로 반올림 (Node 내장에 안정된 float16 배열이 없어 직접 흉내 · 아주 작은 수는 무시)
  if (v === 0) return 0;
  const q = 2 ** (Math.floor(Math.log2(Math.abs(v))) - 10);
  return Math.round(v / q) * q;
}

const ref = matmul(X, W);
const W16 = W.map(f16);
const y16 = matmul(X.map(f16), W16);
const scale = W.reduce((m, v) => Math.max(m, Math.abs(v)), 0) / 127; // int8: 가장 큰 값을 127에 맞추는 대칭 양자화
