  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

class FakeSocket {
  // WebSocket 흉내: 손님 → 서버, 서버 → 손님 두 줄 (진짜 네트워크 없음)
  toServer: { audio_ms: number; chars: number }[] = [];
  toClient: { spans: [string, number, number][]; firstSound: number }[] = [];
}

const STAGES: Record<string, (audioMs: number, chars: number) => number> = {
  // 구간별 걸리는 시간(ms) = 고정 + 길이에 비례 (모의 서비스)
  "ws 수신": () => 5,
  asr: (a) => 80 + 0.1 * a,
  llm: (_a, c) => 250 + 4 * c,
  tts: (_a, c) => 40 + 3 * c,
};

function serverTurn(sock: FakeSocket, clock: { t: number }): void {
  // api 서버 한 턴: 받은 소리를 asr → llm → tts 순서로 처리하고 구간별 시각을 기록해 돌려준다 (가상 시계 사용)
  const msg = sock.toServer.shift()!;
  const spans: [string, number, number][] = [];
  for (const [name, ms] of Object.entries(STAGES)) {
    const t0 = clock.t;
    clock.t += ms(msg.audio_ms, msg.chars) / 1000;
    spans.push([name, t0, clock.t]);
  }
  const [, tts0, tts1] = spans[spans.length - 1];
  sock.toClient.push({ spans, firstSound: tts0 + 0.4 * (tts1 - tts0) }); // TTS는 40% 만든 첫 조각부터 내보냄
}

const health = (): Record<string, string> => Object.fromEntries(["asr", "llm", "tts", "api"].map((n) => [n, "ok"])); // 서비스 넷의 /health (모의)

check(JSON.stringify(health()) === '{"asr":"ok","llm":"ok","tts":"ok","api":"ok"}', "서비스 넷이 모두 ok여야 통화를 시작해요.");

const sock = new FakeSocket();
const clock = { t: 0 };
const turns: [number, number][] = [[1200, 20], [2500, 45], [1800, 30]]; // (손님 말 길이 ms, 비서 답 글자 수)
const results: [number, number, number, string][] = [];
for (const [audioMs, chars] of turns) {
  const start = clock.t;
  sock.toServer.push({ audio_ms: audioMs, chars }); // 손님: 말이 끝나면 소리를 보냄
  serverTurn(sock, clock);
  const reply = sock.toClient.shift()!;
  const total = clock.t - start;
  const slow = reply.spans.reduce((m, s) => (s[2] - s[1] > m[2] - m[1] ? s : m));
  console.log(`턴 말 ${audioMs}ms · 답 ${chars}자 | ` + reply.spans.map(([n, a, b]) => `${n} ${((b - a) * 1000).toFixed(0)}ms`).join(" ")
    + ` | 첫 소리 ${((reply.firstSound - start) * 1000).toFixed(0)}ms · 답 도착 ${(total * 1000).toFixed(0)}ms · 가장 느린 곳 ${slow[0]}`);
  results.push([total, reply.spans.reduce((s, [, a, b]) => s + (b - a), 0), reply.firstSound - start, slow[0]]);
}
check(results.every(([t, s, f, w]) => Math.abs(t - s) < 1e-9 && f < t && w === "llm"), "구간 시간의 합이 총 시간과 같고, 첫 소리는 답 도착보다 빠르고, 가장 느린 곳은 llm이어야 해요.");

