const GPU_WON_PER_HOUR = 1500; // GPU 한 장의 시간당 요금 (원, 가상의 값)
const CALL_SECONDS = 180; // 통화 한 건의 평균 길이

function costPerCall(cap: number): number {
  // 통화당 원가(원, 정수): 시간당 요금 ÷ 한 시간에 처리하는 통화 수, 올림 (금액은 정수)
  const callsPerHour = Math.floor((cap * 3600) / CALL_SECONDS);
  return Math.ceil(GPU_WON_PER_HOUR / callsPerHour);
}

for (const [name, cfg] of [["최적화 전", NOBATCH], ["마이크로 배치 후", BATCHED]] as [string, Cfg][]) {
  const cap = capacity(cfg);
  const perHour = Math.floor((cap * 3600) / CALL_SECONDS);
  console.log(`${name}: 수용량 ${cap}통화 → 한 시간 ${perHour}건 → 통화당 ${costPerCall(cap)}원 (GPU ${GPU_WON_PER_HOUR}원/시간)`);
}
check(costPerCall(10) === 8 && costPerCall(53) === 2 && costPerCall(1) === 75, "1500원 ÷ 200건 = 7.5 → 올림 8원, 53통화는 1500 ÷ 1060 → 2원, 1통화는 75원이어야 해요.");
check([1, 10, 53].every((n) => Number.isInteger(costPerCall(n))), "금액은 정수(원)로 다뤄요.");

