import { createHash } from "node:crypto";

const FILES: Record<string, string> = { "requirements.txt": "numpy==2.4.6", src: "v1" };
type Layer = [string, number, string[]];
// (명령, 걸리는 초, 복사하는 파일) — 복사 파일이 바뀐 층부터 아래는 캐시를 못 쓴다
const GOOD: Layer[] = [["FROM python:3.11-slim", 5, []], ["COPY requirements.txt .", 1, ["requirements.txt"]],
  ["RUN pip install -r requirements.txt", 60, []], ["COPY src/ .", 1, ["src"]]];
const BAD: Layer[] = [["FROM python:3.11-slim", 5, []], ["COPY . .", 1, ["requirements.txt", "src"]],
  ["RUN pip install -r requirements.txt", 60, []]];

function build(dockerfile: Layer[], files: Record<string, string>, cache: Set<string>): [number, number] {
  // 층마다 (위 층까지의 열쇠 + 명령 + 복사한 파일 내용)의 해시가 전과 같으면 캐시를 쓴다 → [걸린 초, 다시 쓴 층 수]
  let key = "", total = 0, reused = 0;
  for (const [cmd, cost, reads] of dockerfile) {
    key = createHash("sha256").update(key + cmd + reads.map((f) => files[f]).join("")).digest("hex");
    if (cache.has(key)) reused++;
    else { cache.add(key); total += cost; }
  }
  return [total, reused];
}

function rebuildAfterEdit(dockerfile: Layer[]): [number, number, number] {
  const cache = new Set<string>();
  const [cold] = build(dockerfile, FILES, cache); // 처음 빌드
  const [again, reused] = build(dockerfile, { ...FILES, src: "v2" }, cache); // 소스 한 줄만 고치고 다시
  return [cold, again, reused];
}

type Service = { boot: number; depends_on: string[] };
// compose.yaml의 services 부분을 객체로 옮긴 것 (boot = 건강해질 때까지 걸리는 초, 모의 값)
const SERVICES: Record<string, Service> = {
  asr: { boot: 8, depends_on: [] },
  llm: { boot: 20, depends_on: [] },
  tts: { boot: 6, depends_on: [] },
  api: { boot: 2, depends_on: ["asr", "llm", "tts"] }, // 건강 검사를 통과한 뒤에만 시작
};

function upTiers(services: Record<string, Service>): string[][] {
  // depends_on을 지키는 시작 순서: 같이 띄워도 되는 서비스끼리 한 층으로 (순환이면 오류)
  let left = { ...services };
  const done = new Set<string>();
  const tiers: string[][] = [];
  while (Object.keys(left).length) {
    const tier = Object.keys(left).filter((n) => left[n].depends_on.every((d) => done.has(d))).sort();
    if (!tier.length) throw new Error("depends_on이 서로를 기다려요: " + Object.keys(left).sort().join(", "));
    tiers.push(tier);
    tier.forEach((n) => done.add(n));
    left = Object.fromEntries(Object.entries(left).filter(([n]) => !done.has(n)));
  }
  return tiers;
}

function upTime(services: Record<string, Service>): number {
  // 모두 건강해지는 시각: 서비스 하나의 시각 = 의존 서비스 중 가장 늦은 시각 + 자기 boot
  const t: Record<string, number> = {};
  for (const tier of upTiers(services)) for (const n of tier) t[n] = Math.max(0, ...services[n].depends_on.map((d) => t[d])) + services[n].boot;
  return Math.max(...Object.values(t));
}

interface Cfg { service: (n: number) => number; window: number; maxSize: number }

function splitBatches(arrivals: number[], window: number, maxSize: number): number[][] {
  // 도착 시각(초)을 묶음으로: 묶음의 첫 요청이 온 뒤 window 안에 온 것을 최대 maxSize개까지
  const groups: number[][] = [];
  let i = 0;
  while (i < arrivals.length) {
    let j = i + 1;
    while (j < arrivals.length && j - i < maxSize && arrivals[j] < arrivals[i] + window) j++;
    groups.push(arrivals.slice(i, j));
    i = j;
  }
  return groups;
}

function percentile(xs: number[], p: number): number {
  const s = [...xs].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.max(0, Math.ceil((p / 100) * s.length) - 1))];
}

function serve(arrivals: number[], cfg: Cfg): number[] {
  // GPU 한 장(모의 서버) = 한 번에 묶음 하나. window 동안 모아 묶고 묶음 하나를 service(n)초에 처리 → 요청별 응답 시간(초)
  let free = 0, i = 0;
  const lat: number[] = [];
  while (i < arrivals.length) {
    const t = Math.max(free, arrivals[i]);
    let j = i + 1;
    while (j < arrivals.length && j - i < cfg.maxSize && arrivals[j] <= t + cfg.window) j++;
    const start = j - i === cfg.maxSize ? Math.max(t, arrivals[j - 1]) : t + cfg.window;
    const done = start + cfg.service(j - i);
    for (const a of arrivals.slice(i, j)) lat.push(done - a);
    free = done; i = j;
  }
  return lat;
}

function calls(n: number, turns = 6, every = 2.0): number[] {
  // 가상 통화 n개: 통화마다 every초에 한 번 말하고, 시작 시각은 고르게 엇갈림 (부하 생성기)
  const xs: number[] = [];
  for (let i = 0; i < n; i++) for (let k = 0; k < turns; k++) xs.push((i * every) / n + k * every);
  return xs.sort((a, b) => a - b);
}

const NOBATCH: Cfg = { service: () => 0.2, window: 0, maxSize: 1 }; // 최적화 전: 요청마다 0.2초
const BATCHED: Cfg = { service: (n) => 0.15 + 0.02 * n, window: 0.05, maxSize: 8 }; // 최적화 후: 묶으면 묶음 하나에 0.15 + 0.02n초
const SLO = 1.0; // p95 응답이 1초 안이어야 '버틴다'

function capacity(cfg: Cfg, slo = SLO): number {
  // p95가 slo를 넘기 전까지 동시에 받을 수 있는 통화 수
  let best = 0;
  for (let n = 1; n <= 60; n++) {
    if (percentile(serve(calls(n), cfg), 95) > slo) break;
    best = n;
  }
  return best;
}

const GPU_WON_PER_HOUR = 1500; // GPU 한 장의 시간당 요금 (원, 가상의 값)
const CALL_SECONDS = 180; // 통화 한 건의 평균 길이

function costPerCall(cap: number): number {
  // 통화당 원가(원, 정수): 시간당 요금 ÷ 한 시간에 처리하는 통화 수, 올림 (금액은 정수)
  const callsPerHour = Math.floor((cap * 3600) / CALL_SECONDS);
  return Math.ceil(GPU_WON_PER_HOUR / callsPerHour);
}

